    file_pattern = r'={50}\nFile: ' + re.escape(file_path) + r'\n={50}\n(.*?)(?=\n={50}\nFile:|\Z)'
    match = re.search(file_pattern, content, re.DOTALL)
    if match:
        return match.group(1)
    return None

